interface Command {
  execute(): void;
  undo(): void;
}

class DrawShapeCommand implements Command {
  constructor(private canvas: Canvas, private shape: Shape) {}
  execute() { this.canvas.drawShape(this.shape); }
  undo() { this.canvas.removeShape(this.shape); }
}

class CommandHistory {
  private history: Command[] = [];
  execute(command: Command) {
    command.execute();
    this.history.push(command);
  }
  undo() {
    this.history.pop()?.undo();
  }
}

const history = new CommandHistory();
drawButton.onclick = () => history.execute(new DrawShapeCommand(canvas, new Circle(10, 10, 5)));
undoButton.onclick = () => history.undo();
